with activity as (
    select distinct customer_unique_id, date_trunc('month',purchased_at)::date as month
    from "olist"."marts"."fct_orders" where order_status='delivered'
), membership as (
    select customer_unique_id, min(month) as cohort from activity group by 1
), sizes as (
    select cohort,count(*) as cohort_size from membership group by 1
), observed as (
    select m.cohort, a.month, count(*) as active_customers
    from membership m join activity a using(customer_unique_id) group by 1,2
), grid as (
    select s.*, generate_series(cohort,date_trunc('month','2018-08-31'::date),interval '1 month')::date as month
    from sizes s
)
select g.*, (extract(year from age(g.month,g.cohort))*12+extract(month from age(g.month,g.cohort)))::int as month_number,
       coalesce(o.active_customers,0) as active_customers,
       coalesce(o.active_customers,0)::numeric/g.cohort_size as retention
from grid g left join observed o using(cohort,month)

with seller_orders as (
    select i.seller_id, o.order_id, sum(i.price) as gmv,
           max(o.review_score) as order_review_score, bool_or(o.is_late) as is_late
    from "olist"."staging"."stg_order_items" i join "olist"."marts"."fct_orders" o using(order_id)
    where o.order_status='delivered' group by 1,2
), sellers as (
    select seller_id,count(*) as orders,sum(gmv) as gmv,
           avg(order_review_score) as mean_order_review_score,avg(is_late::int) as late_rate
    from seller_orders group by 1
)
select s.*, d.state, rank() over(order by gmv desc) as gmv_rank
from sellers s join "olist"."staging"."stg_sellers" d using(seller_id)

with sales as (
    select date_trunc('month',o.purchased_at)::date as month,
           coalesce(t.category_english,p.category,'unknown') as category, sum(i.price) as gmv
    from "olist"."staging"."stg_order_items" i join "olist"."marts"."fct_orders" o using(order_id)
    left join "olist"."staging"."stg_products" p using(product_id)
    left join "olist"."staging"."stg_product_category_name_translation" t using(category)
    where o.order_status='delivered' group by 1,2
), grid as (
    select distinct m.month,c.category from "olist"."marts"."monthly_sales" m cross join (select distinct category from sales) c
), filled as (
    select g.*,coalesce(s.gmv,0) as gmv from grid g left join sales s using(month,category)
), compared as (
    select *,lag(gmv) over(partition by category order by month) as previous_gmv from filled
)
select *,gmv-previous_gmv as change_brl,100*(gmv/nullif(previous_gmv,0)-1) as mom_pct from compared
